import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForHist,validHist,advanceHist,numericHist}from './hist-models.js?v=20261023-physicscomplete01';import{showHist}from './hist-visuals.js?v=20261023-physicscomplete01';export{showHist};
export function mountHist(l,p,root,{save,done,feedback}){let ts=tasksForHist(l.widget.slice(5)),w=p.widget;w.histTask??=ts[0].id;w.histDrafts??={};w.histPassed??=[];let i=ts.findIndex(t=>t.id===w.histTask);if(i<0)i=0;let t=ts[i],v=w.histDrafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountHist(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.histPassed.includes(t.id));
syncProcessMovie(l,1,!['adult-clone','plant-clone','embryo','speciation','fossil-process'].includes(t.kind)?{process:false}:null);
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('histCase','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('histAnswer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealHist">Reveal evidence →</button><p id="histReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showHist(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#histReadout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validHist(c,v.answer);}
else if(t.type==='sequence'){body=field('histNext','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceHist">Advance pathway →</button><p id="histReadout" aria-live="polite"></p>';draw=()=>{showHist(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#histReadout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else{body='<p>'+t.prompt+'</p><label class="field-label" for="histNumber">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="histNumber" type="number" step="any" value="'+(v.number??'')+'">'+field('histReason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showHist(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericHist(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="histEvidence"></p><div class="lab-actions"><button class="secondary" id="recordHist">Record reasoning</button><button class="secondary" id="nextHist">Next challenge →</button></div><p id="histProgress"></p>';
const status=()=>{$('#histEvidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.histPassed.includes(t.id)?'Challenge recorded.':'';$('#histProgress').textContent=ts.filter(t=>w.histPassed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='histCase'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='histAnswer')v.answer=val;else if(id==='histNext')v.next=val;else if(id==='histNumber')v.number=val;else if(id==='histReason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v.number=e.target.value;save();};}
if($('#revealHist'))$('#revealHist').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validHist(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validHist(t.cases[v.case],v.answer));};
if($('#advanceHist'))$('#advanceHist').onclick=()=>{let n=advanceHist(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordHist').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);let finished=t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.histPassed.includes(t.id))w.histPassed.push(t.id);p.widgetDone=ts.every(t=>w.histPassed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextHist').onclick=()=>{if(!w.histPassed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.histTask=ts[(i+1)%ts.length].id;save();remount();};}
